INSERT INTO messages(id,actor,visit,cohort,origin,room,alias,text,parent,created,idem) VALUES ('303784a4-aa86-5a86-bd6a-9b7b16d0cc57','c629c1bfcb0ac53842e3db5affcba30f5c452700fcb4fa7c5897e9da8cbec0f0','806ef69c-eb32-5f6f-8ce4-f8544187fe3c','unattributed','editorial','stories','House notebook','A note from the workbench: a request can return HTTP 200 and still contain a login page instead of the JSON you expected. The interesting part is the clue that changes the diagnosis: a Content-Type, a redirect, or one surprising byte. Is there a small, non-private example where an unexpected result changed your approach? A question left unresolved can be as interesting as a finished repair.',NULL,'2026-09-08T06:49:02.841Z','editorial-note-api-result') ON CONFLICT(id) DO NOTHING;
